/* =============================================================================
   INV-07 · Panel de lista de exclusión — estilos.
   Ningún color literal: todo sale de las variables `--bw-*` (§1 del sistema).
   ========================================================================== */

.panel {
  display: flex;
  flex-direction: column;
  gap: 20px;
  margin: 0 0 20px;
  padding: 24px;
  background: var(--bw-warm-cream);
  border: 1px solid var(--bw-line-steel);
  border-radius: var(--bw-radius);
}

.section {
  display: block;
}

.subTitle {
  margin: 0 0 10px;
  font-family: var(--bw-font-title);
  font-size: var(--bw-size-label);
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: var(--bw-ls-label);
  color: var(--bw-ink-steel);
}

/* ── Exclusión por organización ─────────────────────────────────────────── */

.search {
  width: 100%;
  padding: var(--bw-pad-input);
  background: var(--bw-surface-mist);
  border: 1px solid var(--bw-line-steel-strong);
  border-radius: var(--bw-radius);
  font-family: var(--bw-font-body);
  font-size: var(--bw-size-input);
  color: var(--bw-input-text);
  outline: none;
}

.search::placeholder {
  color: var(--bw-input-placeholder);
}

.search:focus {
  border-color: var(--bw-calibration-blue);
  box-shadow: var(--bw-focus-halo);
}

.search:disabled {
  color: var(--bw-hint-steel);
  cursor: not-allowed;
}

.hint {
  margin: 6px 0 0;
  font-family: var(--bw-font-mono);
  font-size: var(--bw-size-hint);
  text-transform: uppercase;
  letter-spacing: var(--bw-ls-hint);
  color: var(--bw-input-placeholder);
}

.candidates {
  display: flex;
  flex-direction: column;
  gap: 4px;
  margin: 8px 0 0;
  padding: 0;
  list-style: none;
}

.candidate {
  width: 100%;
  padding: 8px 10px;
  text-align: left;
  background: var(--bw-surface-mist);
  border: 1px solid var(--bw-line-steel-strong);
  border-radius: var(--bw-radius);
  font-family: var(--bw-font-body);
  font-size: var(--bw-size-input);
  color: var(--bw-deep-steel);
  cursor: pointer;
  transition: border-color 0.12s, background 0.12s;
}

.candidate:hover {
  background: var(--bw-hover-surface);
  border-color: var(--bw-hover-border);
}

/* ── Etiquetas (organización y geografía) ───────────────────────────────── */

.tags {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin-top: 10px;
}

.tag {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 4px 10px;
  background: var(--bw-chip-active-bg);
  border: 1px solid var(--bw-chip-active-border);
  border-radius: 20px;
  font-family: var(--bw-font-body);
  font-size: var(--bw-size-label);
  font-weight: 500;
  color: var(--bw-deep-steel);
}

.tagGeo {
  background: var(--bw-tag-bg);
  border-color: var(--bw-tag-border);
}

.tagLabel {
  white-space: nowrap;
}

.tagRemove {
  display: inline-flex;
  align-items: center;
  padding: 0;
  background: none;
  border: none;
  font-family: inherit;
  font-size: var(--bw-size-eyebrow);
  line-height: 1;
  color: var(--bw-steel-mist);
  cursor: pointer;
}

.tagRemove:hover:not(:disabled) {
  color: var(--bw-danger-light);
}

.tagRemove:disabled {
  color: var(--bw-hint-steel);
  cursor: not-allowed;
}

/* ── Exclusión por geografía ────────────────────────────────────────────── */

.geoRow {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-end;
  gap: 8px;
}

.field {
  display: flex;
  flex-direction: column;
  gap: 4px;
  flex: 1 1 160px;
  min-width: 0;
}

.fieldLabel {
  font-family: var(--bw-font-body);
  font-size: var(--bw-size-label);
  font-weight: 500;
  color: var(--bw-ink-steel);
}

.select {
  width: 100%;
  padding: var(--bw-pad-input);
  background: var(--bw-surface-mist);
  border: 1px solid var(--bw-line-steel-strong);
  border-radius: var(--bw-radius);
  font-family: var(--bw-font-body);
  font-size: var(--bw-size-input);
  color: var(--bw-input-text);
  outline: none;
  cursor: pointer;
}

.select:focus {
  border-color: var(--bw-calibration-blue);
  box-shadow: var(--bw-focus-halo);
}

.select:disabled {
  color: var(--bw-hint-steel);
  cursor: not-allowed;
}

.addGeo {
  height: 36px;
  padding: 0 14px;
  background: var(--bw-deep-steel);
  border: none;
  border-radius: var(--bw-radius);
  font-family: var(--bw-font-body);
  font-size: var(--bw-size-input);
  font-weight: 500;
  color: var(--bw-warm-cream);
  cursor: pointer;
  transition: background 0.12s;
}

.addGeo:hover:not(:disabled) {
  background: var(--bw-deep-steel-darkest);
}

.addGeo:focus-visible {
  outline: none;
  box-shadow: var(--bw-focus-halo);
}

.addGeo:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

/* ── Error de la última exclusión ───────────────────────────────────────── */

.error {
  margin: 0;
  padding: 10px 12px;
  background: var(--bw-sensitive-bg);
  border: 1px solid var(--bw-badge-danger-border);
  border-radius: var(--bw-radius);
  font-family: var(--bw-font-body);
  font-size: var(--bw-size-input);
  line-height: 1.5;
  color: var(--bw-error-text);
}

/*
 * Panel inactivo (`data-active="false"`): los controles ya van `disabled` por
 * atributo, así que aquí solo se apaga el color. Nada de `pointer-events: none`
 * ni `opacity: 0` — las etiquetas siguen visibles, en gris, y los tests pueden
 * seguir leyéndolas.
 */
.panel[data-active='false'] .search,
.panel[data-active='false'] .select {
  color: var(--bw-hint-steel);
  background: var(--bw-surface-mist);
  border-color: var(--bw-line-steel);
}

.panel[data-active='false'] .fieldLabel,
.panel[data-active='false'] .hint,
.panel[data-active='false'] .tagLabel,
.panel[data-active='false'] .candidate {
  color: var(--bw-hint-steel);
}

import type { Zone } from '../../lib/search';
import {
  CONTINENT_OPTIONS,
  type CountryOption,
  type Exclusion,
  type OrgCandidate,
} from '../../lib/visibility';
import styles from './ExclusionPanel.module.css';

interface Props {
  /** Las exclusiones de tipo organización, ya agrupadas y ordenadas por la pantalla. */
  orgs: Exclusion[];
  /** Las exclusiones geográficas (continente y país juntos), ya agrupadas. */
  geo: Exclusion[];
  /** Candidatos del autocompletado: `filterOrgCandidates` los calcula la pantalla. */
  candidates: OrgCandidate[];
  query: string;
  continent: Zone | '';
  country: string;
  countries: CountryOption[];
  /** Modo «visible para todos» o miembro sin permiso: la lista queda inactiva pero visible. */
  disabled: boolean;
  /** Hay una llamada en vuelo. */
  busy: boolean;
  /** Error de la última exclusión: `role="alert"` dentro del panel. */
  error: string | null;
  onQueryChange: (q: string) => void;
  onPickOrg: (c: OrgCandidate) => void;
  onContinentChange: (c: Zone | '') => void;
  onCountryChange: (code: string) => void;
  onAddGeo: () => void;
  onRemove: (e: Exclusion) => void;
}

/**
 * Panel de lista de exclusión de INV-07 (spec §3). Presentacional: sin red y sin
 * estado propio — `query`, `continent` y `country` llegan por props y cada gesto
 * se devuelve hacia arriba. Las exclusiones se escriben al momento, así que este
 * panel no conoce el botón de guardar.
 */
export function ExclusionPanel({
  orgs,
  geo,
  candidates,
  query,
  continent,
  country,
  countries,
  disabled,
  busy,
  error,
  onQueryChange,
  onPickOrg,
  onContinentChange,
  onCountryChange,
  onAddGeo,
  onRemove,
}: Props) {
  return (
    <div
      className={styles.panel}
      data-testid="exclusion-panel"
      data-active={disabled ? 'false' : 'true'}
    >
      {/* ── Subsección 1: por organización ── */}
      <section className={styles.section} aria-label="Exclusión por organización">
        <h2 className={styles.subTitle}>Exclusión por organización</h2>

        <input
          type="text"
          className={styles.search}
          placeholder="Buscar organización por nombre..."
          value={query}
          disabled={disabled}
          onChange={(e) => onQueryChange(e.target.value)}
        />

        <p className={styles.hint}>EFECTO INMEDIATO AL AÑADIR</p>

        {/* Sin candidatos no hay lista: el desplegable solo existe con coincidencias. */}
        {candidates.length > 0 && (
          <ul className={styles.candidates}>
            {candidates.map((candidate) => (
              <li key={candidate.id}>
                <button
                  type="button"
                  className={styles.candidate}
                  onClick={() => onPickOrg(candidate)}
                >
                  {candidate.name}
                </button>
              </li>
            ))}
          </ul>
        )}

        <div className={styles.tags}>
          {orgs.map((exclusion) => (
            <span key={exclusion.id} className={styles.tag}>
              <span className={styles.tagLabel}>{exclusion.label}</span>
              <button
                type="button"
                className={styles.tagRemove}
                aria-label={'Quitar ' + exclusion.label}
                disabled={disabled || busy}
                onClick={() => onRemove(exclusion)}
              >
                ×
              </button>
            </span>
          ))}
        </div>
      </section>

      {/* ── Subsección 2: por geografía ── */}
      <section className={styles.section} aria-label="Exclusión por geografía">
        <h2 className={styles.subTitle}>Exclusión por geografía</h2>

        <div className={styles.geoRow}>
          <label className={styles.field}>
            <span className={styles.fieldLabel}>Excluir por continente</span>
            <select
              className={styles.select}
              value={continent}
              disabled={disabled}
              onChange={(e) => onContinentChange(e.target.value as Zone | '')}
            >
              <option value="">Selecciona un continente</option>
              {CONTINENT_OPTIONS.map((option) => (
                <option key={option.code} value={option.code}>
                  {option.label}
                </option>
              ))}
            </select>
          </label>

          {/* El select de país solo aparece tras elegir continente. */}
          {continent !== '' && (
            <label className={styles.field}>
              <span className={styles.fieldLabel}>Refinar por país</span>
              <select
                className={styles.select}
                value={country}
                disabled={disabled}
                onChange={(e) => onCountryChange(e.target.value)}
              >
                <option value="">Todos los países del continente</option>
                {countries.map((option) => (
                  <option key={option.code} value={option.code}>
                    {option.label}
                  </option>
                ))}
              </select>
            </label>
          )}

          <button
            type="button"
            className={styles.addGeo}
            disabled={disabled || busy || continent === ''}
            onClick={onAddGeo}
          >
            Añadir exclusión geográfica
          </button>
        </div>

        <p className={styles.hint}>EXCLUYE TODAS LAS ORGANIZACIONES CON SEDE EN ESA GEOGRAFÍA</p>

        <div className={styles.tags}>
          {geo.map((exclusion) => (
            <span key={exclusion.id} className={`${styles.tag} ${styles.tagGeo}`}>
              <span className={styles.tagLabel}>{exclusion.label}</span>
              <button
                type="button"
                className={styles.tagRemove}
                aria-label={'Quitar ' + exclusion.label}
                disabled={disabled || busy}
                onClick={() => onRemove(exclusion)}
              >
                ×
              </button>
            </span>
          ))}
        </div>
      </section>

      {error !== null && (
        <p className={styles.error} role="alert">
          {error}
        </p>
      )}
    </div>
  );
}

