/* =============================================================================
   INV-07 · Configuración de Visibilidad del Inventario — estilos de la pantalla.
   Ningún color literal: todo sale de las variables `--bw-*` de
   `openspec/architecture/design-system.md` §1. El sistema no define un token de
   blanco puro para las tarjetas del mock; el más cercano es `--bw-warm-cream`
   (#FAF8F4) y es el que se usa como superficie de tarjeta.
   ========================================================================== */

/*
 * La raíz es hija DIRECTA de `.bwcnt`, que es `overflow: hidden`: sin estas
 * cuatro declaraciones el contenido se recorta sin barra de scroll (F-186/F-189).
 */
.screen {
  display: flex;
  flex-direction: column;
  flex: 1;
  min-height: 0;
  overflow-y: auto;
}

.eyebrow {
  font-family: var(--bw-font-title);
  font-size: var(--bw-size-eyebrow);
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: var(--bw-ls-eyebrow);
  color: var(--bw-steel-mist);
  margin-bottom: 6px;
}

.title {
  font-family: var(--bw-font-title);
  font-size: var(--bw-size-title);
  font-weight: 700;
  letter-spacing: var(--bw-ls-title);
  color: var(--bw-deep-steel);
  margin: 0 0 6px;
}

.subtitle {
  font-family: var(--bw-font-body);
  font-size: var(--bw-size-body);
  line-height: 1.6;
  color: var(--bw-steel-mist);
  max-width: 600px;
  margin: 0 0 24px;
}

/* ── Mensajes ───────────────────────────────────────────────────────────── */

.alert {
  margin: 0 0 16px;
  padding: 10px 12px;
  background: var(--bw-sensitive-bg);
  border: 1px solid var(--bw-badge-danger-border);
  border-radius: var(--bw-radius);
  font-family: var(--bw-font-body);
  font-size: var(--bw-size-input);
  line-height: 1.5;
  color: var(--bw-error-text);
}

.status {
  margin: 14px 0 0;
  padding: 10px 14px;
  background: var(--bw-badge-success-bg);
  border: 1px solid var(--bw-badge-success-border);
  border-radius: var(--bw-radius);
  font-family: var(--bw-font-body);
  font-size: var(--bw-size-input);
  line-height: 1.5;
  color: var(--bw-success-dark);
}

.readOnly {
  margin: 0 0 16px;
  padding: 10px 12px;
  background: var(--bw-surface-mist);
  border: 1px solid var(--bw-line-steel);
  border-radius: var(--bw-radius);
  font-family: var(--bw-font-body);
  font-size: var(--bw-size-input);
  line-height: 1.5;
  color: var(--bw-ink-steel-soft);
}

/* ── Selector de modo ───────────────────────────────────────────────────── */

.modeCard {
  display: flex;
  flex-direction: column;
  min-width: 0;
  margin: 0 0 20px;
  padding: 24px;
  background: var(--bw-warm-cream);
  border: 1px solid var(--bw-line-steel);
  border-radius: var(--bw-radius);
}

.legend {
  padding: 0;
  margin-bottom: 14px;
  font-family: var(--bw-font-title);
  font-size: var(--bw-size-label);
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: var(--bw-ls-label);
  color: var(--bw-steel-mist);
}

.radioGroup {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.radio {
  display: grid;
  grid-template-columns: auto 1fr;
  align-items: start;
  column-gap: 12px;
  row-gap: 3px;
  padding: var(--bw-pad-radio);
  background: var(--bw-surface-mist);
  border: 1px solid var(--bw-line-steel);
  border-radius: var(--bw-radius);
  cursor: pointer;
  transition: border-color 0.15s, background 0.15s;
}

.radio:hover {
  border-color: var(--bw-calibration-blue);
}

.radioSelected {
  border-color: var(--bw-calibration-blue);
  background: var(--bw-chip-active-bg);
}

.radioInput {
  grid-column: 1;
  grid-row: 1;
  margin: 2px 0 0;
  accent-color: var(--bw-calibration-blue);
}

.radioLabel {
  grid-column: 2;
  grid-row: 1;
  font-family: var(--bw-font-body);
  font-size: var(--bw-size-eyebrow);
  font-weight: 600;
  color: var(--bw-deep-steel);
}

.radioDesc {
  grid-column: 2;
  grid-row: 2;
  font-family: var(--bw-font-body);
  font-size: var(--bw-size-input);
  line-height: 1.5;
  color: var(--bw-steel-mist);
}

/* ── Aviso brass de la lista conservada ─────────────────────────────────── */

.brassNotice {
  margin: 0 0 20px;
  padding: 10px 14px;
  background: var(--bw-tag-bg);
  border: 1px solid var(--bw-brass-border-soft);
  border-radius: var(--bw-radius);
  font-family: var(--bw-font-body);
  font-size: var(--bw-size-input);
  line-height: 1.5;
  color: var(--bw-ink-steel-soft);
}

/* ── Bloque informativo brass (siempre) ─────────────────────────────────── */

.infoBlock {
  margin: 0 0 20px;
  padding: 12px 14px;
  background: var(--bw-tag-bg);
  border: 1px solid var(--bw-brass-border);
  border-radius: var(--bw-radius);
}

.infoText {
  margin: 0;
  font-family: var(--bw-font-body);
  font-size: var(--bw-size-input);
  line-height: 1.5;
  color: var(--bw-ink-steel-soft);
}

/* ── Guardar ────────────────────────────────────────────────────────────── */

.save {
  align-self: flex-start;
  height: 40px;
  padding: 0 22px;
  background: var(--bw-calibration-blue);
  border: none;
  border-radius: var(--bw-radius);
  font-family: var(--bw-font-body);
  font-size: var(--bw-size-eyebrow);
  font-weight: 500;
  color: var(--bw-warm-cream);
  cursor: pointer;
  transition: background 0.12s;
}

.save:hover:not(:disabled) {
  background: var(--bw-primary-dark);
}

.save:focus-visible {
  outline: none;
  box-shadow: var(--bw-focus-halo);
}

.save:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

