import { useEffect, useState } from 'react';
import type { Zone } from '../../lib/search';
import { errorMessage, type MemberProfile } from '../../lib/session';
import {
  addExclusion,
  canManageVisibility,
  DEFAULT_VISIBILITY_MODE,
  fetchContinentCountries,
  fetchOrgCandidates,
  fetchVisibility,
  filterOrgCandidates,
  groupExclusions,
  IMMEDIATE_EFFECT_NOTICE,
  KEPT_LIST_NOTICE,
  READ_ONLY_NOTICE,
  removeExclusion,
  SAVED_MESSAGE,
  saveVisibilityMode,
  VISIBILITY_MODES,
  type CountryOption,
  type Exclusion,
  type OrgCandidate,
  type VisibilityMode,
} from '../../lib/visibility';
import { ExclusionPanel } from './ExclusionPanel';
import styles from './Visibility.module.css';

const EYEBROW = 'Módulo 02 · Gestión de Inventario';
const TITLE = 'Visibilidad del inventario';
const SUBTITLE =
  'Controla quién puede ver tu stock en Bearingworld.io. El modo se aplica a todo tu inventario de forma inmediata.';

/** Texto del `<legend>` y nombre accesible del `<fieldset role="radiogroup">`. */
const MODE_LEGEND = 'Modo de visibilidad';

const SAVE_LABEL = 'Guardar configuración';

interface Props {
  /** La sesión del miembro: de aquí salen `orgId` y `role`. INV-07 la usa para todo. */
  profile: MemberProfile;
}

/**
 * INV-07 — Configuración de Visibilidad del Inventario. La pantalla posee TODO el
 * estado: el modo guardado, el borrador del radio (que no toca la red hasta
 * `Guardar configuración`), la lista de exclusiones y el estado del formulario de
 * geografía. `ExclusionPanel` es presentacional y no llama a nada.
 *
 * Las exclusiones, en cambio, SÍ son de efecto inmediato (spec §3): se escriben al
 * añadir o quitar y solo entonces se vuelve a pedir la lista.
 */
export function Visibility({ profile }: Props) {
  /** Modo GUARDADO en el servidor. Solo cambia al guardar con éxito. */
  const [savedMode, setSavedMode] = useState<VisibilityMode>(DEFAULT_VISIBILITY_MODE);
  /** Modo del radio (borrador). Cambiarlo NO llama a ninguna función de red. */
  const [draftMode, setDraftMode] = useState<VisibilityMode>(DEFAULT_VISIBILITY_MODE);
  const [exclusions, setExclusions] = useState<Exclusion[]>([]);

  /** El directorio completo de organizaciones: lo filtra `filterOrgCandidates`, no la pantalla. */
  const [allOrgs, setAllOrgs] = useState<OrgCandidate[]>([]);
  const [query, setQuery] = useState('');
  const [continent, setContinent] = useState<Zone | ''>('');
  const [country, setCountry] = useState('');
  const [countries, setCountries] = useState<CountryOption[]>([]);

  /** Error de la carga inicial (spec §3): `role="alert"` de la pantalla. */
  const [loadError, setLoadError] = useState<string | null>(null);
  /** Error de una exclusión (añadir o quitar): viaja a la prop `error` del panel. */
  const [panelError, setPanelError] = useState<string | null>(null);
  /** Error de `Guardar configuración`: `role="alert"` de la pantalla. */
  const [saveError, setSaveError] = useState<string | null>(null);
  /** Éxito del guardado: uno solo a la vez, `role="status"`. */
  const [notice, setNotice] = useState<string | null>(null);
  /** Hay una llamada en vuelo: deshabilita las acciones del panel y el guardado. */
  const [busy, setBusy] = useState(false);

  /** Solo el ADMIN escribe (`exclusions_write_admin`, `0002`); un EDITOR solo lee. */
  const canManage = canManageVisibility(profile.role);
  const panelDisabled = draftMode === 'VISIBLE_TODOS' || !canManage;

  /*
   * Una sola vez al montar: el modo guardado y la lista completa de exclusiones.
   * El borrador arranca igual que el guardado — el radio nunca se re-sincroniza
   * después, para no pisar lo que el usuario está eligiendo.
   */
  useEffect(() => {
    let active = true;

    fetchVisibility(profile.orgId)
      .then((state) => {
        if (!active) return;
        setSavedMode(state.mode);
        setDraftMode(state.mode);
        setExclusions(state.exclusions);
      })
      .catch((e: unknown) => {
        if (!active) return;
        setLoadError(errorMessage(e));
      });

    return () => {
      active = false;
    };
  }, [profile.orgId]);

  /** El directorio de organizaciones, una sola vez: el filtrado es de cliente. */
  useEffect(() => {
    let active = true;

    fetchOrgCandidates()
      .then((list) => {
        if (!active) return;
        setAllOrgs(list);
      })
      .catch((e: unknown) => {
        if (!active) return;
        setLoadError(errorMessage(e));
      });

    return () => {
      active = false;
    };
  }, []);

  /** Repide la lista tras una exclusión que ha ido bien. NO toca el borrador del radio. */
  async function reloadExclusions(): Promise<void> {
    const state = await fetchVisibility(profile.orgId);
    setExclusions(state.exclusions);
  }

  async function pickOrg(candidate: OrgCandidate): Promise<void> {
    setBusy(true);
    setPanelError(null);
    try {
      await addExclusion(profile.orgId, { orgId: candidate.id });
      await reloadExclusions();
      setQuery('');
    } catch (e: unknown) {
      // Sin recarga y sin limpiar el buscador: solo el error (spec §3, «si falla»).
      setPanelError(errorMessage(e));
    } finally {
      setBusy(false);
    }
  }

  async function addGeo(): Promise<void> {
    // El botón ya va deshabilitado sin continente, pero el contrato lo repite aquí.
    if (country === '' && continent === '') return;
    setBusy(true);
    setPanelError(null);
    try {
      if (country !== '') {
        await addExclusion(profile.orgId, { country });
      } else if (continent !== '') {
        await addExclusion(profile.orgId, { continent });
      }
      await reloadExclusions();
      setContinent('');
      setCountry('');
      setCountries([]);
    } catch (e: unknown) {
      setPanelError(errorMessage(e));
    } finally {
      setBusy(false);
    }
  }

  async function remove(exclusion: Exclusion): Promise<void> {
    setBusy(true);
    setPanelError(null);
    try {
      await removeExclusion(exclusion.id);
      await reloadExclusions();
    } catch (e: unknown) {
      setPanelError(errorMessage(e));
    } finally {
      setBusy(false);
    }
  }

  async function save(): Promise<void> {
    setBusy(true);
    setSaveError(null);
    // Un solo `role="status"` a la vez: el aviso anterior se retira antes de intentar.
    setNotice(null);
    try {
      await saveVisibilityMode(profile.orgId, draftMode);
      setSavedMode(draftMode);
      setNotice(SAVED_MESSAGE);
    } catch (e: unknown) {
      // Sin status: solo el error.
      setSaveError(errorMessage(e));
    } finally {
      setBusy(false);
    }
  }

  function handlePickOrg(candidate: OrgCandidate): void {
    void pickOrg(candidate);
  }

  function handleAddGeo(): void {
    void addGeo();
  }

  function handleRemove(exclusion: Exclusion): void {
    void remove(exclusion);
  }

  function handleSave(): void {
    void save();
  }

  function handleContinentChange(code: Zone | ''): void {
    setContinent(code);
    setCountry('');
    if (code === '') {
      setCountries([]);
      return;
    }
    setPanelError(null);
    void (async () => {
      try {
        const list = await fetchContinentCountries(code);
        setCountries(list);
      } catch (e: unknown) {
        setPanelError(errorMessage(e));
      }
    })();
  }

  function handleCountryChange(code: string): void {
    setCountry(code);
  }

  function handleQueryChange(next: string): void {
    setQuery(next);
  }

  const grouped = groupExclusions(exclusions);
  const candidates = filterOrgCandidates(allOrgs, query, exclusions, profile.orgId);
  /** El panel solo existe en restringido o si queda algo guardado (spec §6). */
  const showPanel = draftMode === 'RESTRINGIDA' || exclusions.length > 0;

  return (
    <div className={styles.screen} data-saved-mode={savedMode}>
      <div className={styles.eyebrow}>{EYEBROW}</div>
      <h1 className={styles.title}>{TITLE}</h1>
      <p className={styles.subtitle}>{SUBTITLE}</p>

      {loadError !== null && (
        <p className={styles.alert} role="alert">
          {loadError}
        </p>
      )}

      {/* ── Solo lectura: se dice antes de ofrecer nada que la base vaya a rechazar. ── */}
      {!canManage && <p className={styles.readOnly}>{READ_ONLY_NOTICE}</p>}

      {/* ── Los dos modos, en el orden de `VISIBILITY_MODES`. El radio mueve el
          borrador y nada más: la red solo se toca al guardar. ── */}
      <fieldset className={styles.modeCard} role="radiogroup" aria-label={MODE_LEGEND}>
        <legend className={styles.legend}>{MODE_LEGEND}</legend>
        <div className={styles.radioGroup}>
          {VISIBILITY_MODES.map((mode) => (
            <label
              key={mode.value}
              className={mode.value === draftMode ? `${styles.radio} ${styles.radioSelected}` : styles.radio}
            >
              <input
                className={styles.radioInput}
                type="radio"
                name="visibility-mode"
                value={mode.value}
                checked={mode.value === draftMode}
                disabled={!canManage}
                onChange={() => setDraftMode(mode.value)}
              />
              <span className={styles.radioLabel}>{mode.label}</span>
              <span className={styles.radioDesc}>{mode.description}</span>
            </label>
          ))}
        </div>
      </fieldset>

      {/* ── Aviso brass: la lista no se borra al volver a «visible para todos». ── */}
      {draftMode === 'VISIBLE_TODOS' && exclusions.length > 0 && (
        <p className={styles.brassNotice}>{KEPT_LIST_NOTICE}</p>
      )}

      {/* ── La lista de exclusión: solo si el modo la usa o si hay algo guardado. ── */}
      {showPanel && (
        <ExclusionPanel
          orgs={grouped.orgs}
          geo={grouped.geo}
          candidates={candidates}
          query={query}
          continent={continent}
          country={country}
          countries={countries}
          disabled={panelDisabled}
          busy={busy}
          error={panelError}
          onQueryChange={handleQueryChange}
          onPickOrg={handlePickOrg}
          onContinentChange={handleContinentChange}
          onCountryChange={handleCountryChange}
          onAddGeo={handleAddGeo}
          onRemove={handleRemove}
        />
      )}

      {/* ── Bloque brass: siempre, en los dos modos y también en solo lectura. ── */}
      <div className={styles.infoBlock}>
        <p className={styles.infoText}>{IMMEDIATE_EFFECT_NOTICE}</p>
      </div>

      <button
        type="button"
        className={styles.save}
        onClick={handleSave}
        disabled={!canManage || busy}
      >
        {SAVE_LABEL}
      </button>

      {notice !== null && (
        <p className={styles.status} role="status">
          {notice}
        </p>
      )}

      {saveError !== null && (
        <p className={styles.alert} role="alert">
          {saveError}
        </p>
      )}
    </div>
  );
}
